window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["contrastive-learning"]={"title":"对比学习：用正对与负对塑造表示空间","subtitle":"从 InfoNCE、温度与梯度方向，到增强不变性、大批量、假负样本、表示坍缩和迁移验收。","thesis":"对比学习不直接规定每个样本的类别，而是规定哪些视图应靠近、哪些候选应远离。真正定义表示语义的是<b>正对构造、负样本分布、增强策略与采样偏差</b>；同一个损失既能学到语义，也能学到背景、水印或实例指纹。","quality":{"contractVersion":2,"examples":[{"section":3,"evidence":{"setup":"锚点 A、正视图 A⁺、负样本鞋 B 和汽车 C","rule":"温度 τ=0.2","steps":"54.60/76.34","interpretation":"B 的 0.263 带来比 C 的 0.022 更强推远信号"}}],"termReviews":[{"section":1,"reviewedAt":"2026-07-26","terms":[{"name":"特征向量","meaning":"编码器把一张视图转换成的数值表示","purpose":"让视图关系可计算并让下游任务读取特征","definitionEvidence":"把它映射为特征向量 z","purposeEvidence":"下游可使用投影前表示"}]},{"section":10,"reviewedAt":"2026-07-26","terms":[{"name":"高维","meaning":"一个表示由许多数值坐标共同组成","purpose":"保存编码器学到的多种特征信息","definitionEvidence":"高维表示","purposeEvidence":"目标任务和反事实切片验收"},{"name":"降维","meaning":"把高维坐标有损映射到更少坐标","purpose":"让人可视化检查可疑簇和离群点","definitionEvidence":"可视化降维方法","purposeEvidence":"适合发现可疑簇和离群点"},{"name":"t-SNE","meaning":"强调局部邻近关系的非线性可视化降维方法","purpose":"辅助观察表示中的局部簇与异常","definitionEvidence":"t-SNE 与 UMAP 都是把高维表示有损映射","purposeEvidence":"适合发现可疑簇和离群点"},{"name":"UMAP","meaning":"基于邻域图结构的非线性可视化降维方法","purpose":"辅助观察表示的邻域与整体布局","definitionEvidence":"二维或三维的可视化降维方法","purposeEvidence":"会改变原空间距离"}]}],"formulas":[{"id":"contrastive-infonce","section":2,"formulaIndex":1,"symbols":[{"name":"ℓ","meaning":"当前锚点正样本的负对数概率损失","evidence":"ℓᵢ 是锚点 i 的正样本负对数概率损失"},{"name":"i","meaning":"当前锚点的样本编号","evidence":"i 是当前锚点编号"},{"name":"log","meaning":"将正样本概率转换为可优化的负对数损失","evidence":"正样本负对数概率损失"},{"name":"exp","meaning":"把缩放后的候选相似度指数化","evidence":"exp 和 Σ 将全部候选分数归一化成概率"},{"name":"sim","meaning":"比较锚点和候选表示的相似度函数","evidence":"sim 是相似度函数"},{"name":"z","meaning":"锚点、正视图或候选样本的向量表示","evidence":"zᵢ 是它的向量"},{"name":"τ","meaning":"缩放相似度差异的温度参数","evidence":"τ 是缩放相似度的温度"},{"name":"Σ","meaning":"对候选集合所有指数分数求和","evidence":"将全部候选分数归一化成概率"},{"name":"j","meaning":"候选正负样本的遍历索引","evidence":"j 遍历候选集合中的正负样本"}]},{"id":"moco-momentum-update","section":7,"formulaIndex":1,"symbols":[{"name":"θ","meaning":"带 key 或 query 下标的编码器参数","evidence":"θ_key 是生成队列 key 的编码器参数"},{"name":"m","meaning":"控制旧 key 参数保留比例的动量系数","evidence":"m 是接近 1 的动量系数"}]},{"id":"contrastive-vicreg-objective","section":9,"formulaIndex":1,"symbols":[{"name":"L","meaning":"总损失及三个带下标的组成损失项","evidence":"L 是总损失"},{"name":"λ","meaning":"方差防坍缩项的权重","evidence":"λ 和 μ 是后两项权重"},{"name":"μ","meaning":"协方差去冗余项的权重","evidence":"λ 和 μ 是后两项权重"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"对比学习用正对与负对关系塑造编码器的向量表示空间。","evidence":"谁与谁相同”的关系表"},"problem":{"answer":"它无需类别名称也能让同一对象视图靠近并区分其他对象。","evidence":"没有类别名称"},"inputOutput":{"answer":"输入原始样本生成的多种视图，输出编码器特征和对比空间向量。","evidence":"映射到专门计算对比损失的空间"},"mechanism":{"answer":"同源视图构成正对，其他样本构成负对，规则提供隐式关系标签。","evidence":"构造规则事实上给出了隐式关系标签"},"interpretation":{"answer":"A 与 A⁺ 应靠近；B、C 是否该远离取决于任务对“相同”的定义。","evidence":"锚点 A 是一张鞋图"},"boundary":{"answer":"投影头可隔离训练空间与下游表示，但不能修复错误的正负关系构造。","evidence":"让下游可使用投影前表示"}},{"section":2,"definition":{"answer":"InfoNCE 把一个锚点的正视图当作候选集合中的正确临时类别。","evidence":"让一个正样本与整组候选竞争"},"problem":{"answer":"它把关系学习转为在正负候选之间提高正样本概率的分类式目标。","evidence":"为什么它看起来像一个临时分类任务"},"inputOutput":{"answer":"输入锚点、正视图、候选向量和温度，输出正样本概率损失。","evidence":"分母包含正对和负对"},"mechanism":{"answer":"相似度除温度后指数归一化，拉高正 logit 并按概率压低负 logit。","evidence":"按当前 softmax 概率推低负对"},"interpretation":{"answer":"较相似负样本拥有更高 softmax 概率，因此收到更大推远梯度。","evidence":"候选中的正对是正确类别"},"boundary":{"answer":"通常须先归一化向量，否则模型可能只靠增大范数降低损失。","evidence":"避免模型仅靠增大范数降低损失"}},{"section":3,"definition":{"answer":"手算例将三项相似度经温度、指数和归一化得到损失与梯度强度。","evidence":"完整手算：相似鞋比汽车贡献更大梯度"},"problem":{"answer":"它说明困难负样本为何比简单负样本对一次更新影响更大。","evidence":"相似度 [0.8,0.6,0.1] 如何变成损失"},"inputOutput":{"answer":"输入 A 与 A⁺、B、C 的相似度，输出概率 0.715 和损失 0.335。","evidence":"正对概率 p⁺=54.60/76.34"},"mechanism":{"answer":"相似度除以 0.2，指数化后用总和归一化，最后取正对负对数。","evidence":"第一步除以温度得 logits"},"interpretation":{"answer":"B 概率 0.263 大于 C 的 0.022，所以 B 受到更强推远信号。","evidence":"交叉熵对其 logit 的导数就是当前 softmax 概率"},"boundary":{"answer":"B 对实例检索可为合理困难负例，对鞋类语义则可能是假负例。","evidence":"若目标是鞋类语义"}},{"section":4,"definition":{"answer":"温度 τ 是在 softmax 前缩放所有相似度差异的参数。","evidence":"温度控制模型关注多难的负样本"},"problem":{"answer":"它控制训练聚焦最高分困难候选还是让多候选共同贡献。","evidence":"既能强化区分，也会放大噪声"},"inputOutput":{"answer":"输入相似度与 τ，输出尖锐或平滑的候选概率和对应梯度。","evidence":"使 softmax 集中在最高的几个候选"},"mechanism":{"answer":"τ 变小放大 logit 间隔，τ 变大压缩间隔并趋向均匀分布。","evidence":"τ 太大则概率近均匀"},"interpretation":{"answer":"小温度让困难负样本主导更新，大温度使区分压力变弱。","evidence":"困难负样本获得更大梯度"},"boundary":{"answer":"温度必须与 batch、向量归一化和标签噪声联合调节。","evidence":"必须与 batch、相似度归一化和数据噪声一起调"}},{"section":5,"definition":{"answer":"表示空间由正对拉近、负对推远的采样关系共同雕刻。","evidence":"增强与采样共同雕刻空间"},"problem":{"answer":"它直观呈现困难负例与假负例使用同一推远动作却语义可能相反。","evidence":"同一个锚点周围"},"inputOutput":{"answer":"输入 A、A⁺、B、C 的构造关系，输出它们在表示空间的移动方向。","evidence":"哪些点被拉近、哪些被推远"},"mechanism":{"answer":"训练拉近正视图并推远候选负例，推力取决于相似度与概率。","evidence":"拉近 A⁺；推远 B、C"},"interpretation":{"answer":"B 是困难负还是错误假负，必须由下游语义而非损失自身判断。","evidence":"取决于下游语义定义"},"boundary":{"answer":"损失只能执行给定关系，无法自行知道采样关系是否符合产品任务。","evidence":"损失只知道构造出的关系"}},{"section":6,"definition":{"answer":"数据增强通过把两种视图设为正对来声明某种变化不影响语义。","evidence":"增强定义模型应忽略哪些变化"},"problem":{"answer":"它减少位置、色彩或措辞捷径，却可能删掉真正决定标签的信息。","evidence":"随机裁剪不是无害的数据处理"},"inputOutput":{"answer":"输入原样本与裁剪、颜色或回译规则，输出被拉近的正视图对。","evidence":"两视图之间的差异"},"mechanism":{"answer":"视图差异在优化中被压缩，模型被迫对该变化近似不敏感。","evidence":"被声明为“不影响语义”"},"interpretation":{"answer":"小目标被裁掉或否定实体被改写，说明增强破坏了任务标签。","evidence":"否定或实体被替换"},"boundary":{"answer":"合理增强依赖领域：医学侧别、熟度颜色等不能照搬自然图像配方。","evidence":"旋转改变医学方位"}},{"section":7,"definition":{"answer":"MoCo 用历史 key 队列和慢更新动量编码器提供大量较一致负样本。","evidence":"解决的是负样本供给"},"problem":{"answer":"它避免为了更多负样本把超大 batch 一次全部放入显存。","evidence":"为什么不用把超大 batch 一次塞进显存"},"inputOutput":{"answer":"输入 query 编码器参数和旧 key 参数，输出平滑更新的 key 编码器。","evidence":"生成队列 key 的编码器参数"},"mechanism":{"answer":"key 参数保留 m 比例旧值并吸收 1−m 比例当前 query 参数。","evidence":"坐标系变化更缓慢"},"interpretation":{"answer":"慢更新让不同时间进入队列的 key 相对可比，但队列过旧仍会漂移。","evidence":"队列太旧会产生表示漂移"},"boundary":{"answer":"大 batch 和跨设备共享增加通信与假负率，更多负例并非单调收益。","evidence":"不能把“更多负样本”当单调收益"}},{"section":8,"definition":{"answer":"假负样本是按采样规则标为负对、按目标语义却应相近的样本。","evidence":"假负样本会把同类语义撕裂"},"problem":{"answer":"它解释同类鞋被推远时模型究竟学实例身份还是类别语义。","evidence":"两张不同鞋图被当负对"},"inputOutput":{"answer":"输入任务语义及候选关系，输出合理负例、假负例或假正例判断。","evidence":"关系标签必须与时间、身份和任务语义一致"},"mechanism":{"answer":"实例区分允许同类互斥，类别检索则需多正样本或过滤同类候选。","evidence":"监督对比的多正样本"},"interpretation":{"answer":"正负关系不是自然事实，而是对具体下游相同概念的建模决定。","evidence":"正负不是自然事实"},"boundary":{"answer":"近邻挖掘、伪标签和去偏损失会引入新误差，且还须检查假正样本。","evidence":"但都会引入新误差"}},{"section":9,"definition":{"answer":"表示坍缩是不同输入映射为近乎同一向量、失去区分信息。","evidence":"不同输入都输出近乎相同向量"},"problem":{"answer":"它防止只拉近正对的一致性目标以常数向量获得完美损失。","evidence":"全部输出同一个向量不是完美答案吗"},"inputOutput":{"answer":"输入正对视图，输出既一致又保持维度方差与多样性的表示。","evidence":"维持各维方差并惩罚冗余协方差"},"mechanism":{"answer":"停止梯度与教师学生制造不对称，VICReg 另加方差和协方差约束。","evidence":"用停止梯度、教师—学生或预测头"},"interpretation":{"answer":"损失正常但标准差、有效秩或邻居多样性下降仍表示部分或全部坍缩。","evidence":"loss 正常下降不能排除"},"boundary":{"answer":"无显式负样本方法仍需特定防坍缩机制，不能只监控训练损失。","evidence":"仍需防止表示坍缩"}},{"section":10,"definition":{"answer":"表示验收用下游探测、检索、微调与反事实切片验证学到的信息。","evidence":"表示必须用目标任务和反事实切片验收"},"problem":{"answer":"它发现低训练损失却只识别水印、背景或设备等捷径的模型。","evidence":"模型没有只认水印"},"inputOutput":{"answer":"输入冻结表示和受控切片，输出线性、kNN、Recall@k 与反事实指标。","evidence":"做 kNN/Recall@k"},"mechanism":{"answer":"交换背景颜色水印设备，若主体不变时结果大幅变动则暴露捷径。","evidence":"交换背景、颜色、水印或拍摄设备"},"interpretation":{"answer":"降维图只用于发现异常，不能单独证明真实簇、公平或检索质量。","evidence":"不能单独证明真实簇结构"},"boundary":{"answer":"比较模型必须固定骨干、数据、增强、预算和协议并覆盖分布外切片。","evidence":"必须固定骨干、数据、增强、训练预算和评测协议"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>逐步计算 InfoNCE；解释温度与困难负样本；设计不破坏语义的增强；诊断假负、坍缩与捷径。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>训练信号是一张“谁与谁相同”的关系表<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">没有类别名称，模型凭什么知道两张图要靠近？</p><p>从同一原始样本产生两种视图作为正对；其他样本作为负对。编码器 <code>f</code> 接收一张视图并把它映射为特征向量 <code>z</code>；投影头 <code>g</code> 再把 z 映射到专门计算对比损失的空间，让下游可使用投影前表示。构造规则事实上给出了隐式关系标签。</p><div class=\"dd-note\"><b>贯穿例子：</b>锚点 A 是一张鞋图，A⁺ 是其裁剪，B 是另一双鞋，C 是汽车。余弦相似度分别为0.8、0.6、0.1，温度 τ=0.2。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>InfoNCE 让一个正样本与整组候选竞争<span class=\"dd-badge math\">公式</span></h2><p class=\"dd-lead\">为什么它看起来像一个临时分类任务？</p><div class=\"dd-formula\">ℓᵢ=−log exp(sim(zᵢ,zᵢ⁺)/τ) / Σ<sub>j∈candidates</sub> exp(sim(zᵢ,zⱼ)/τ)</div><p><b>符号逐个解释：</b><code>i</code> 是当前锚点编号，<code>zᵢ</code> 是它的向量，<code>zᵢ⁺</code> 是正视图向量；<code>j</code> 遍历候选集合中的正负样本，<code>zⱼ</code> 是候选向量；<code>sim</code> 是相似度函数，<code>τ</code> 是缩放相似度的温度；<code>exp</code> 和 <code>Σ</code> 将全部候选分数归一化成概率，<code>ℓᵢ</code> 是锚点 i 的正样本负对数概率损失。</p><p>把锚点当查询，候选中的正对是正确类别。分母包含正对和负对；损失拉高正对 logit，同时按当前 softmax 概率推低负对。通常先归一化向量，避免模型仅靠增大范数降低损失。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>完整手算：相似鞋比汽车贡献更大梯度<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">相似度 [0.8,0.6,0.1] 如何变成损失？</p><p>沿用锚点 A、正视图 A⁺、负样本鞋 B 和汽车 C，温度 τ=0.2。第一步除以温度得 logits [4,3,0.5]；第二步取指数约 [54.60,20.09,1.65]；总和76.34；正对概率 p⁺=54.60/76.34≈<b>0.715</b>；损失 −log0.715≈<b>0.335</b>。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>候选</th><th>相似度</th><th>softmax概率</th><th>训练作用</th></tr></thead><tbody><tr><td>A⁺ 正对</td><td>0.8</td><td>0.715</td><td>继续拉近</td></tr><tr><td>B 鞋</td><td>0.6</td><td>0.263</td><td>强力推远</td></tr><tr><td>C 汽车</td><td>0.1</td><td>0.022</td><td>梯度很小</td></tr></tbody></table></div><p>对负候选而言，交叉熵对其 logit 的导数就是当前 softmax 概率；所以 B 的 0.263 带来比 C 的 0.022 更强推远信号。若目标是实例检索，这种困难负样本合理；若目标是鞋类语义，B 可能是假负样本。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>温度控制模型关注多难的负样本<span class=\"dd-badge math\">温度</span></h2><p class=\"dd-lead\">τ 变小为何既能强化区分，也会放大噪声？</p><p>τ 缩小会放大相似度差异，使 softmax 集中在最高的几个候选；困难负样本获得更大梯度。τ 太大则概率近均匀、信号弱；τ 太小遇到错配或假负时会猛烈推开本应相近的样本。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>τ</th><th>分布</th><th>风险</th></tr></thead><tbody><tr><td>较小</td><td>尖锐，聚焦 hard negatives</td><td>噪声敏感、梯度不稳</td></tr><tr><td>较大</td><td>平滑，多候选共同作用</td><td>区分压力不足</td></tr></tbody></table></div><p>温度可固定或学习，但必须与 batch、相似度归一化和数据噪声一起调。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>原创图：增强与采样共同雕刻空间<span class=\"dd-badge intuition\">可视化</span></h2><p class=\"dd-lead\">同一个锚点周围，哪些点被拉近、哪些被推远？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 735 310\" role=\"img\" aria-label=\"对比学习中锚点正样本困难负样本和简单负样本的移动\"><defs><marker id=\"cta\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#788293\"/></marker></defs><rect x=\"20\" y=\"35\" width=\"180\" height=\"240\" rx=\"10\" fill=\"#21252d\" stroke=\"#596273\"/><text x=\"110\" y=\"62\" text-anchor=\"middle\" class=\"svg-t\">数据构造</text><text x=\"55\" y=\"105\" class=\"svg-t\">A 锚点</text><text x=\"55\" y=\"142\" class=\"svg-t\">A⁺ 裁剪</text><text x=\"55\" y=\"179\" class=\"svg-t\">B 另一双鞋</text><text x=\"55\" y=\"216\" class=\"svg-t\">C 汽车</text><path d=\"M200,155 L295,155\" stroke=\"#788293\" marker-end=\"url(#cta)\"/><rect x=\"305\" y=\"35\" width=\"405\" height=\"240\" rx=\"10\" fill=\"#21252d\" stroke=\"#596273\"/><circle cx=\"480\" cy=\"155\" r=\"12\" fill=\"#d3a05a\"/><text x=\"480\" y=\"184\" text-anchor=\"middle\" class=\"svg-t\">A</text><circle cx=\"575\" cy=\"100\" r=\"11\" fill=\"#65a6d9\"/><text x=\"595\" y=\"98\" class=\"svg-t\">A⁺ 正对</text><path d=\"M563,107 L500,144\" stroke=\"#65a6d9\" stroke-width=\"3\" marker-end=\"url(#cta)\"/><circle cx=\"565\" cy=\"210\" r=\"11\" fill=\"#cf7c72\"/><text x=\"585\" y=\"214\" class=\"svg-t\">B hard / false negative</text><path d=\"M500,164 L548,198\" stroke=\"#cf7c72\" stroke-width=\"3\" marker-end=\"url(#cta)\"/><circle cx=\"670\" cy=\"245\" r=\"9\" fill=\"#778293\"/><text x=\"620\" y=\"265\" class=\"svg-t\">C easy negative</text><text x=\"500\" y=\"67\" class=\"svg-t\">拉近 A⁺；推远 B、C</text></svg><figcaption>图 1　损失只知道构造出的关系；B 是合理困难负样本还是错误假负样本，取决于下游语义定义。</figcaption></figure></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>增强定义模型应忽略哪些变化<span class=\"dd-badge eng\">不变性</span></h2><p class=\"dd-lead\">为什么随机裁剪不是无害的数据处理？</p><p>正对被拉近，所以两视图之间的差异被声明为“不影响语义”。裁剪训练位置与局部缺失不变，颜色抖动训练色彩不变，回译训练措辞不变。若颜色决定熟度、旋转改变医学方位、裁剪删掉主体，目标就会压掉有用信息。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>领域</th><th>可能合理</th><th>可能破坏标签</th></tr></thead><tbody><tr><td>自然图像</td><td>轻微裁剪/颜色</td><td>小目标被裁掉</td></tr><tr><td>医学影像</td><td>有限噪声</td><td>左右翻转改变侧别</td></tr><tr><td>文本</td><td>保义改写</td><td>否定或实体被替换</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>大 batch、队列和动量编码器解决的是负样本供给<span class=\"dd-badge eng\">系统</span></h2><p class=\"dd-lead\">MoCo 为什么不用把超大 batch 一次塞进显存？</p><p>SimCLR 用大 batch 获得更多负样本；MoCo 把历史 key 放入队列，并用缓慢更新的动量编码器保持旧、新向量坐标相对一致。跨设备 all-gather 可共享负样本，但增加通信。</p><div class=\"dd-formula\">θ<sub>key</sub>←mθ<sub>key</sub>+(1−m)θ<sub>query</sub></div><p><b>式中：</b><code>θ_key</code> 是生成队列 key 的编码器参数，<code>θ_query</code> 是当前通过梯度训练的查询编码器参数；<code>m</code> 是接近 1 的动量系数。每一步让 key 编码器保留 m 比例的旧参数、吸收 1−m 比例的新 query 参数，因此坐标系变化更缓慢。</p><p>队列太旧会产生表示漂移；batch 大也会提高假负率。系统吞吐与统计目标必须联合设计，不能把“更多负样本”当单调收益。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>假负样本会把同类语义撕裂<span class=\"dd-badge intuition\">采样边界</span></h2><p class=\"dd-lead\">两张不同鞋图被当负对，模型到底在学什么？</p><p>实例区分希望每张图独特，因此同类可当负；类别检索希望同类聚集，此时它是假负。缓解方法包括监督对比的多正样本、近邻挖掘、去偏损失、聚类伪标签或过滤高相似候选，但都会引入新误差。</p><p>还要警惕假正样本：同一视频相邻帧可能已经切镜，同一患者两次检查可能病情改变。关系标签必须与时间、身份和任务语义一致。</p><div class=\"dd-note warn\"><b>正负不是自然事实。</b>它们是面向某个下游任务的建模决定。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>没有负样本的方法仍需防止表示坍缩<span class=\"dd-badge math\">BYOL/VICReg</span></h2><p class=\"dd-lead\">若只最小化正对距离，全部输出同一个向量不是完美答案吗？</p><p>是。“表示坍缩”就是不同输入都输出近乎相同向量，朴素一致性损失允许这种常数解。BYOL/SimSiam 用停止梯度、教师—学生或预测头形成不对称；VICReg 显式维持各维方差并惩罚冗余协方差。</p><div class=\"dd-formula\">L=L<sub>invariance</sub>+λL<sub>variance</sub>+μL<sub>covariance</sub></div><p><b>式中：</b><code>L</code> 是总损失，<code>L_invariance</code> 拉近正对，<code>L_variance</code> 防止各维失去变化，<code>L_covariance</code> 减少维度间冗余；<code>λ</code> 和 <code>μ</code> 是后两项权重。训练时要看每维标准差、协方差谱、有效秩与最近邻多样性。loss 正常下降不能排除部分维度或全部样本坍缩。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">10</span>表示必须用目标任务和反事实切片验收<span class=\"dd-badge eng\">评测</span></h2><p class=\"dd-lead\">训练 loss 很低，怎样知道模型没有只认水印？</p><ol><li>冻结编码器做线性探测，测线性可读信息。</li><li>做 kNN/Recall@k，检查最近邻语义和少数类。</li><li>固定预算少样本微调，测数据效率。</li><li>交换背景、颜色、水印或拍摄设备，做反事实测试。</li><li>按来源、群体和分布外数据切片。</li></ol><p>t-SNE 与 UMAP 都是把高维表示有损映射到二维或三维的可视化降维方法，适合发现可疑簇和离群点；它们会改变原空间距离，不能单独证明真实簇结构、公平性或检索质量。比较方法时必须固定骨干、数据、增强、训练预算和评测协议。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">11</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与依赖</span></h2><p class=\"dd-lead\">公式只执行关系，数据构造才定义关系。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>对比学习不需要标签</td><td>正负构造就是关系标签</td></tr><tr><td>负样本越多越好</td><td>覆盖与假负率同时增加</td></tr><tr><td>温度越小越能分开</td><td>也会放大噪声和不稳定</td></tr><tr><td>增强越强越鲁棒</td><td>错误不变性会删除任务信息</td></tr><tr><td>低损失证明表示好</td><td>需迁移、检索和反事实验收</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>嵌入、softmax、交叉熵</td></tr><tr><td><b>本页核心</b></td><td>InfoNCE、温度、增强、正负采样</td></tr><tr><td>变体</td><td>SimCLR、MoCo、BYOL、监督对比</td></tr><tr><td>应用</td><td>CLIP、检索、自监督学习</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">12</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>定义下游语义与不变性</li><li>构造正对和候选负对</li><li>编码归一化并计算相似度</li><li>InfoNCE 聚焦困难候选</li><li>监控假负、捷径和坍缩</li><li>用迁移与反事实测试验收</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">13</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>算例中正对概率和损失约多少？</li><li>为什么B鞋获得比C汽车更大梯度？</li><li>温度变小有什么双重效果？</li><li>MoCo的动量编码器解决什么？</li><li>只拉近正对为何会坍缩？</li><li>假设“对比学习：用正对与负对塑造表示空间”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“对比学习：用正对与负对塑造表示空间”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>概率约0.715，损失约0.335。</li><li>B与锚点相似度更高，是困难负样本，softmax概率更大。</li><li>聚焦困难负样本，也放大错配与假负噪声。</li><li>让队列中不同时间生成的key保持相对一致。</li><li>所有样本输出同一常数即可让正对距离为零。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/1807.03748\" target=\"_blank\" rel=\"noopener\">Representation Learning with Contrastive Predictive Coding</a>：InfoNCE 与预测编码</li><li><a href=\"https://arxiv.org/abs/2002.05709\" target=\"_blank\" rel=\"noopener\">A Simple Framework for Contrastive Learning of Visual Representations</a>：SimCLR</li><li><a href=\"https://arxiv.org/abs/1911.05722\" target=\"_blank\" rel=\"noopener\">Momentum Contrast for Unsupervised Visual Representation Learning</a>：MoCo 动量队列</li><li><a href=\"https://arxiv.org/abs/2004.11362\" target=\"_blank\" rel=\"noopener\">Supervised Contrastive Learning</a>：多正样本监督对比</li><li><a href=\"https://arxiv.org/abs/2105.04906\" target=\"_blank\" rel=\"noopener\">VICReg</a>：方差—不变性—协方差约束</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
